public class Partial_with_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial();
        partial.with(null, 10);
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeChronology.getChronology());
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020}, DateTimeChronology.getChronology());

        Partial result = partial.with(yearType, 2020);

        assertSame("Should return the same instance if value is unchanged", partial, result);
    }

    @Test
    public void testWith_ExistingField_DifferentValue_ReturnsNewPartial() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeChronology.getChronology());
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYearOf(DateTimeChronology.getChronology());
        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2020, 1}, DateTimeChronology.getChronology());

        Partial result = partial.with(yearType, 2021);

        assertNotSame(partial, result);
        assertEquals(2, result.size());
        assertEquals(2021, result.getValue(0));
        assertEquals(1, result.getValue(1));
    }

    @Test
    public void testWith_NewField_InsertAtStart() {
        // We use types where the new field's unit is larger than existing
        // e.g., Year is larger than Month
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYearOf(DateTimeChronology.getChronology());
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeChronology.getChronology());

        Partial partial = new Partial(new DateTimeFieldType[]{monthType}, new int[]{5}, DateTimeChronology.getChronology());

        // Adding year should place it before month (largest-smallest order)
        Partial result = partial.with(yearType, 2022);

        assertEquals(2, result.size());
        assertEquals(yearType, result.getFieldType(0));
        assertEquals(2022, result.getValue(0));
        assertEquals(monthType, result.getFieldType(1));
        assertEquals(5, result.getValue(1));
    }

    @Test
    public void testWith_NewField_InsertAtMiddle() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeChronology.getChronology());
        DateTimeFieldType dayType = DateTimeFieldType.dayOfMonthOf(DateTimeChronology.getChronology());
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYearOf(DateTimeChronology.getChronology());

        // Order in array: Year, Day (Wait, logic sorts by unit duration)
        // Chronology order: Year > Month > Day
        Partial partial = new Partial(new DateTimeFieldType[]{yearType, dayType}, new int[]{2020, 15}, DateTimeChronology.getChronology());

        // Adding month should go between year and day
        Partial result = partial.with(monthType, 6);

        assertEquals(3, result.size());
        assertEquals(yearType, result.getFieldType(0));
        assertEquals(monthType, result.getFieldType(1));
        assertEquals(dayType, result.getFieldType(2));
    }

    @Test
    public void testWith_NewField_InsertAtEnd() {
        DateTimeFieldType yearType = DateTimeFieldType.yearOf(DateTimeChronology.getChronology());
        DateTimeFieldType monthType = DateTimeFieldType.monthOfYearOf(DateTimeChronology.getChronology());

        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2020, 1}, DateTimeChronology.getChronology());

        // Adding day should go at the end
        DateTimeFieldType dayType = DateTimeFieldType.dayOfMonthOf(DateTimeChronology.getChronology());
        Partial result = partial.with(dayType, 10);

        assertEquals(3, result.size());
        assertEquals(dayType, result.getFieldType(2));
        assertEquals(10, result.getValue(2));
    }

    @Test
    public void testWith_NewField_CompareUnitSame_CompareRangeDifferent() {
        // This tests the branch: if (compare == 0) { if (rangeField.compareTo(loopRangeField) > 0) break; }
        // We need two field types with the same DurationField but different RangeDurationField.
        // In Joda, this is hard to trigger with standard types, but we can simulate the logic 
        // by ensuring the loop handles the comparison correctly.

        Chronology chrono = DateTimeChronology.getChronology();
        DateTimeFieldType type1 = DateTimeFieldType.yearOf(chrono);
        DateTimeFieldType type2 = DateTimeFieldType.yearOf(chrono); // Same unit

        // Since we can't easily manufacture different range fields for the same unit via public API,
        // we verify the loop completes and inserts if the index is -1.
        Partial partial = new Partial(new DateTimeFieldType[]{type1}, new int[]{2020}, chrono);

        // This will trigger index == -1 because type2 is a different object/instance 
        // even if they represent the same field.
        Partial result = partial.with(type2, 2021);

        assertNotNull(result);
        assertTrue(result.size() >= 1);
    }

